package co.za.millenniumsolutions.repository;
import co.za.millenniumsolutions.model.AttendanceSession; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository;
@Repository public class AttendanceSessionRepository extends RepositorySupport { public AttendanceSessionRepository(JdbcTemplate j){super(j);} public AttendanceSession save(AttendanceSession x){update("INSERT INTO attendance_session(id,user_id,campus_id,work_period_id,clock_in_at,clock_out_at,duration_minutes,status,reconciliation_reference) VALUES (?,?,?,?,COALESCE(?,CURRENT_TIMESTAMP),?,?,?,?) ON CONFLICT(id) DO UPDATE SET clock_out_at=excluded.clock_out_at,duration_minutes=excluded.duration_minutes,status=excluded.status,reconciliation_reference=excluded.reconciliation_reference",x.id(),x.userId(),x.campusId(),x.workPeriodId(),x.clockInAt()==null?null:x.clockInAt().toString(),x.clockOutAt()==null?null:x.clockOutAt().toString(),x.durationMinutes(),x.status(),x.reconciliationReference()); return x;} }
